(()=>{const root=document.querySelector('[data-hero-flow]');if(!root)return;const label=root.querySelector('.hero-flow-lead'),text=root.querySelector('.hero-flow-text'),reduce=matchMedia('(prefers-reduced-motion: reduce)');let index=reduce.matches?3:0,timer,animation,started=false;const phrases={zh:['选一张喜欢的照片','选机型，调成喜欢的样子','保存设计，前往打印','选照片 · 调设计 · 去打印'],en:['Pick a photo you love','Choose your model. Make it yours.','Save your design. Print your case.','Pick a photo · Design · Print']};function sync(){const en=document.documentElement.lang.startsWith('en');label.textContent=en?'From photo to phone case':'从相册到手心';text.textContent=phrases[en?'en':'zh'][index];root.setAttribute('aria-label',en?'From photo to phone case: choose a photo, select your phone model and adjust your design, then save and print.':'从相册到手心：选照片、选机型并调整设计、保存设计并前往打印。');}function next(){if(index>=3||reduce.matches||document.hidden)return;animation=text.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-5px)'}],{duration:160,easing:'ease-in',fill:'forwards'});animation.finished.then(()=>{index++;sync();animation.cancel();animation=text.animate([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,easing:'ease-out'});if(index<3)timer=setTimeout(next,2200);}).catch(()=>{});}function start(){if(started||reduce.matches)return;started=true;timer=setTimeout(next,2200);}new MutationObserver(sync).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});reduce.addEventListener('change',()=>{if(reduce.matches){clearTimeout(timer);animation?.cancel();index=3;sync();}});document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(timer);else if(started&&index<3&&!reduce.matches)timer=setTimeout(next,2200);});sync();if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){start();observer.disconnect();}},{threshold:.5});observer.observe(root);}else start();})();
